  'wander', FALSE, FALSE, NULL, NULL, '/ˈwændər/', 'To move around without a clear destination or purpose.', 'v'
) ON CONFLICT ((LOWER(term))) DO UPDATE SET pronunciation = COALESCE(vocabulary.pronunciation, EXCLUDED.pronunciation), definition_en = COALESCE(vocabulary.definition_en, EXCLUDED.definition_en), part_of_speech = COALESCE(vocabulary.part_of_speech, EXCLUDED.part_of_speech), irregular_forms = COALESCE(vocabulary.irregular_forms, EXCLUDED.irregular_forms);
INSERT INTO meaning (vocab_id, sense_key, definition, explanation_zh, part_of_speech, example_sentence, example_sentence_zh, rank, wordnet_sense_id)
SELECT id, 'v_1', 'To move about aimlessly or without any destination, often in search of food or employment.', '漫无目的地移动或游荡，通常是为了寻找食物或工作。', 'v', 'We wandered through the forest, enjoying the scenery.', '我们漫步在森林中，欣赏着美丽的景色。', 1, 'v#1885173'
FROM vocabulary WHERE LOWER(term) = LOWER('wander')
ON CONFLICT DO NOTHING;
INSERT INTO meaning (vocab_id, sense_key, definition, explanation_zh, part_of_speech, example_sentence, example_sentence_zh, rank, wordnet_sense_id)
SELECT id, 'v_2', 'To be sexually unfaithful to one''s partner in marriage.', '婚内出轨，对伴侣不忠。', 'v', 'Rumors said he had wandered during his marriage.', '有传言说他在婚姻中出轨了。', 2, 'v#2582588'
FROM vocabulary WHERE LOWER(term) = LOWER('wander')
ON CONFLICT DO NOTHING;
INSERT INTO meaning (vocab_id, sense_key, definition, explanation_zh, part_of_speech, example_sentence, example_sentence_zh, rank, wordnet_sense_id)
SELECT id, 'v_3', 'To go via an indirect route or at no set pace.', '走弯路，不按既定路线或速度前进。', 'v', 'After dinner, we wandered into town for a coffee.', '晚餐后，我们漫步到镇上喝咖啡。', 3, 'v#2107118'
FROM vocabulary WHERE LOWER(term) = LOWER('wander')
ON CONFLICT DO NOTHING;

