INSERT INTO meaning (vocab_id, sense_key, definition, explanation_zh, part_of_speech, example_sentence, example_sentence_zh, rank, wordnet_sense_id)
SELECT id, 'adv_1', 'Toward the source of a river or stream; against the current.', '指向上游，逆流而上。', 'adv', 'We paddled upstream for an hour.', '我们逆流划船划了一个小时。', 2, 'r#97658'
FROM vocabulary WHERE LOWER(term) = LOWER('upstream')
ON CONFLICT DO NOTHING;

